#!/bin/bash
# generated by ADIT 0.1.0a1. Runs the runs of the set one by one (they are independent, so a failure does not stop the rest)
cd "$(dirname "$0")"
failed=""
for d in slab molecule adsorbed; do
  echo "== $d"
  bash "$d/submit.sh" || failed="$failed $d"
done
if [ -n "$failed" ]; then echo "failed:$failed" >&2; exit 1; fi
